              "prepare_v_fused expects contiguous NHD [B,S,H,128]");
  TORCH_CHECK(value.scalar_type() == torch::kBFloat16,
              "prepare_v_fused currently supports BF16");
  TORCH_CHECK(value.size(3) == 128, "prepare_v_fused requires D128");
