      {batch, heads, head_dim, seq_pad}, value.options().dtype(torch::kUInt8));
  if (seq_pad > seq_len) {
    output.narrow(3, seq_len, seq_pad - seq_len).zero_();
  }
  torch::Tensor scale = torch::empty(
      {batch, heads, head_dim}, value.options().dtype(torch::kFloat32));
  constexpr int SeqLanes = 8;
