      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()),
      reinterpret_cast<__hip_bfloat16*>(mean.data_ptr<at::BFloat16>()),
