std::vector<torch::Tensor> original_prepare_key_int8_nhd_gfx12(
    torch::Tensor key, torch::Tensor mean) {
  TORCH_CHECK(key.is_cuda() && mean.is_cuda(), "prepare_k expects HIP tensors");
  TORCH_CHECK(key.dim() == 4 && key.is_contiguous(),
              "prepare_k expects contiguous NHD [B,S,H,128]");
  TORCH_CHECK(key.scalar_type() == torch::kBFloat16,
              "prepare_k currently supports BF16");
  TORCH_CHECK(key.size(3) == 128, "prepare_k requires D128");
  TORCH_CHECK(mean.dim() == 4 && mean.size(0) == key.size(0) &&
                  mean.size(1) == 1 && mean.size(2) == key.size(2) &&
                  mean.size(3) == 128 && mean.is_contiguous() &&
                  mean.scalar_type() == key.scalar_type(),
              "prepare_k mean must be contiguous [B,1,H,128] BF16");
  const int64_t batch = key.size(0);
  const int64_t seq_len = key.size(1);
  const int64_t heads = key.size(2);
  torch::Tensor output = torch::empty_like(key, key.options().dtype(torch::kInt8));
  torch::Tensor scale = torch::empty(
      {batch, heads, (seq_len + 63) / 64}, key.options().dtype(torch::kFloat32));
  constexpr int NumPack = 2;
  constexpr int Groups = 4;
  dim3 block(64 * (128 / 8) / NumPack);
  const int64_t k_blocks = (seq_len + 63) / 64;
  dim3 grid((k_blocks + Groups - 1) / Groups, heads, batch);
  const hipStream_t stream = at::hip::getCurrentHIPStreamMasqueradingAsCUDA();
 hipLaunchKernelGGL(( quant_k_nhd_fuse_sub_mean_short_kernel<__hip_bfloat16, 128, NumPack, Groups>)
      , dim3(grid), dim3(block), 0, stream, 
          reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
          reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()),
          output.data_ptr<int8_t>(), scale.data_ptr<float>(), seq_len, heads);
  hip_kernel_launch_check();
  return {output, scale};
}

