__global__ void h3_partial_kv_statistics(
    const __hip_bfloat16* __restrict__ key,
    const __hip_bfloat16* __restrict__ value,
    float* __restrict__ partial, int64_t seq, int64_t heads, int parts) {
  __shared__ float sums[PrepSeqLanes][PrepD];
