    const int64_t off = ((static_cast<int64_t>(b) * seq + s) * heads + h) * PrepD + d;
    __hip_bfloat16 kv[8], vv[8];
#if H3_CENTER_KEY
    *reinterpret_cast<uint4*>(kv) = *reinterpret_cast<const uint4*>(key + off);
#endif
