#pragma unroll
    for (int i = 0; i < 8; ++i) {
#if H3_CENTER_KEY
      sum[i] += __bfloat162float(kv[i]);
#endif
      amax[i] = fmaxf(amax[i], fabsf(__bfloat162float(vv[i])));
    }
  }
#pragma unroll
  for (int i = 0; i < 8; ++i) {
    sums[lane][d + i] = sum[i];
    maxima[lane][d + i] = amax[i];
  }
  __syncthreads();
  if (tid < PrepD) {
    float sum_all = 0.0f, max_all = 0.0f;
#pragma unroll
    for (int i = 0; i < PrepSeqLanes; ++i) {
      sum_all += sums[i][tid];
      max_all = fmaxf(max_all, maxima[i][tid]);
    }
    const int64_t off = ((static_cast<int64_t>(b) * heads + h) * parts + part) * (2 * PrepD);
    partial[off + tid] = sum_all;
    partial[off + PrepD + tid] = max_all;
  }
}

__global__ void h3_reduce_kv_statistics(
    const float* __restrict__ partial, __hip_bfloat16* __restrict__ mean,
    float* __restrict__ scales, int64_t seq, int64_t heads, int parts) {
  const int d = threadIdx.x, h = blockIdx.x, b = blockIdx.y;
  float sum = 0.0f, amax = 0.0f;
  for (int part = 0; part < parts; ++part) {
    const int64_t off = ((static_cast<int64_t>(b) * heads + h) * parts + part) * (2 * PrepD);
    sum += partial[off + d];
    amax = fmaxf(amax, partial[off + PrepD + d]);
  }
  const int64_t off = (static_cast<int64_t>(b) * heads + h) * PrepD + d;
  mean[off] = __float2bfloat16(sum / static_cast<float>(seq));
  scales[off] = amax / 2.25f;
}

