    if (!head_flags[static_cast<int64_t>(b) * heads + h]) return;
  }
  const int64_t s0 = static_cast<int64_t>(H3_HEADS_FIRST ? blockIdx.y : blockIdx.x) * TileS;
  float inv[8], scales_local[8], error_sum[8] = {};
  float local_max[8] = {};
#pragma unroll
  for (int i = 0; i < 8; ++i) {
    if constexpr (UnitScale && !H3_SAMPLE_V_GUARD) {
      inv[i] = 1.0f; scales_local[i] = 1.0f;
    } else {
      const float scale = scales[(static_cast<int64_t>(b) * heads + h) * PrepD + d + i];
      inv[i] = scale == 0.0f ? 0.0f : 1.0f / scale; scales_local[i] = scale;
    }
  }
#pragma unroll
  for (int r = row; r < TileS; r += 16) {
    __hip_bfloat16 values[8];
    if (s0 + r < seq) {
      const int64_t off = ((static_cast<int64_t>(b) * seq + s0 + r) * heads + h) * PrepD + d;
      *reinterpret_cast<uint4*>(values) = *reinterpret_cast<const uint4*>(value + off);
    }
    float decoded[8];
#pragma unroll
    for (int i = 0; i < 8; ++i) {
      decoded[i] = s0 + r < seq ? __bfloat162float(values[i]) : 0.0f;
      if constexpr (UnitScale) local_max[i] = fmaxf(local_max[i], fabsf(decoded[i]));
    }
#if H3_PACKED_CONVERSION
#pragma unroll
    for (int i = 0; i < 8; i += 2) {
      const float x = decoded[i] * inv[i];
      const float y = decoded[i + 1] * inv[i + 1];
      // UnitScale is checked against the exact channel maximum before attention.
      const uint32_t packed = __builtin_amdgcn_cvt_pk_fp8_f32(x, y, 0, false);
      tile[r][d + i] = packed & 255;
      tile[r][d + i + 1] = (packed >> 8) & 255;
      error_sum[i] += fmaf(-__builtin_amdgcn_cvt_f32_fp8(packed, 0), scales_local[i], decoded[i]);
      error_sum[i+1] += fmaf(-__builtin_amdgcn_cvt_f32_fp8(packed, 1), scales_local[i+1], decoded[i+1]);
    }
#else
#pragma unroll
    for (int i = 0; i < 8; ++i) {
      const float x = decoded[i] * inv[i];
      tile[r][d + i] = __hip_cvt_float_to_fp8(x, __HIP_SATFINITE, __HIP_E4M3);
    }
#endif
  }
  if constexpr (UnitScale) {
#pragma unroll
    for (int i = 0; i < 8; ++i) maxima[row][d + i] = local_max[i];
  }
  __syncthreads();
  if constexpr (UnitScale) {
    if (tid < PrepD) {
      float maximum = 0.0f;
#pragma unroll
      for (int i = 0; i < PrepSeqLanes; ++i) maximum = fmaxf(maximum, maxima[i][tid]);
#if H3_V_GUARD_PARTIAL
      const int part = H3_HEADS_FIRST ? blockIdx.y : blockIdx.x;
      const int parts = H3_HEADS_FIRST ? gridDim.y : gridDim.x;
      amax_bits[((static_cast<int64_t>(b)*heads+h)*parts+part)*PrepD+tid] =
          __float_as_uint(maximum);
#else
      atomicMax(amax_bits + (static_cast<int64_t>(b) * heads + h) * PrepD + tid,
                __float_as_uint(maximum));
#endif
    }
  }

  __syncthreads();
#pragma unroll
  for (int i=0; i<8; ++i) maxima[row][d+i] = error_sum[i];
  __syncthreads();
  if (tid < PrepD) {
    float sum = 0.0f;
#pragma unroll
    for (int i=0; i<PrepSeqLanes; ++i) sum += maxima[i][tid];
    const int part = H3_HEADS_FIRST ? blockIdx.y : blockIdx.x;
    const int parts = (seq + TileS - 1) / TileS;
    residuals[((static_cast<int64_t>(b)*heads+h)*parts+part)*PrepD+tid] = sum;
  }
#pragma unroll
  for (int linear = tid; linear < PrepD * (TileS / 4); linear += PrepThreads) {
    const int out_d = linear / (TileS / 4), out_s = (linear % (TileS / 4)) * 4;
    if (s0 + out_s < seq_pad) {
      uint32_t packed = 0;
#pragma unroll
      for (int i = 0; i < 4; ++i) packed |= static_cast<uint32_t>(tile[out_s + i][out_d]) << (8 * i);
      const int64_t off = ((static_cast<int64_t>(b) * heads + h) * PrepD + out_d) * seq_pad + s0 + out_s;
      *reinterpret_cast<uint32_t*>(output + off) = packed;
    }
  }
}
__global__ void h3_choose_value_scale(const float* __restrict__ maxima,
    float* __restrict__ scales, int* __restrict__ head_flags, int64_t heads, int parts) {
  const int64_t h = static_cast<int64_t>(blockIdx.y) * heads + blockIdx.x;
  const int d = threadIdx.x;
#if H3_V_GUARD_PARTIAL
  float maximum = 0.0f;
  for (int part=0; part<parts; ++part)
    maximum = fmaxf(maximum,maxima[(h*parts+part)*PrepD+d]);
#else
  const float maximum = maxima[h * PrepD + d];
#endif
#if H3_SAMPLE_V_GUARD
  const float previous_scale = scales[h * PrepD + d];
  const bool safe = maximum == 0.0f || (previous_scale > 0.0f && maximum <= 448.0f * previous_scale);
  scales[h * PrepD + d] = safe ? previous_scale : maximum / 2.25f;
#else
  // Unit scale cannot underflow more than the original scale when max >= 2.25.
  // The upper bound is the largest finite E4M3 value.
  const bool safe = maximum >= 2.25f && maximum <= 448.0f;
  scales[h * PrepD + d] = safe ? 1.0f : maximum / 2.25f;
#endif
  const int any_fallback = __syncthreads_or(!safe);
  if (d == 0) head_flags[h] = any_fallback;
}

#if H3_GLOBAL_K_SCALE
__global__ void h3_key_global_max(const __hip_bfloat16* __restrict__ key,
    const __hip_bfloat16* __restrict__ mean, unsigned int* __restrict__ maxima,
    int64_t seq, int64_t heads) {
  const int h = blockIdx.x, b = blockIdx.z;
  const int tid = threadIdx.x, d = (tid % 16) * 8, lane = tid / 16;
  const int64_t bh = static_cast<int64_t>(b) * heads + h;
  __hip_bfloat16 means[8];
  *reinterpret_cast<uint4*>(means) = *reinterpret_cast<const uint4*>(mean + bh * PrepD + d);
  float maximum = 1.e-7f;
  const int64_t begin = static_cast<int64_t>(blockIdx.y) * H3_STAT_CHUNK;
  const int64_t end = min(seq, begin + H3_STAT_CHUNK);
  for (int64_t s = begin + lane; s < end; s += PrepSeqLanes) {
    __hip_bfloat16 values[8];
    *reinterpret_cast<uint4*>(values) = *reinterpret_cast<const uint4*>(key + ((static_cast<int64_t>(b)*seq+s)*heads+h)*PrepD+d);
#pragma unroll
    for (int i=0; i<8; ++i) maximum = fmaxf(maximum, fabsf(__bfloat162float(values[i])-__bfloat162float(means[i])));
  }
  const float block_max = vllm::blockReduceMax(maximum);
  if (tid == 0) atomicMax(maxima + bh, __float_as_uint(block_max));
}

__global__ void h3_key_global_quant(const __hip_bfloat16* __restrict__ key,
    const __hip_bfloat16* __restrict__ mean, const float* __restrict__ maxima,
    int8_t* __restrict__ output, float* __restrict__ scales, int64_t seq, int64_t heads) {
  constexpr int Pack = H3_K_PACK, Threads = 1024 / Pack;
  const int tid = threadIdx.x, d = (tid % 16)*8, lane = tid/16;
  const int h = blockIdx.x, b = blockIdx.z;
  const int64_t bh = static_cast<int64_t>(b)*heads+h;
  const int blocks = (seq+63)/64;
  __hip_bfloat16 means[8];
  *reinterpret_cast<uint4*>(means) = *reinterpret_cast<const uint4*>(mean+bh*PrepD+d);
  const float maximum = maxima[bh], inverse = 127.0f/maximum;
  for (int group=0; group<H3_K_GROUPS; ++group) {
    const int block = blockIdx.y*H3_K_GROUPS+group;
    if (block >= blocks) break;
    if (tid == 0 && (!H3_COMPACT_K_SCALE || block == 0))
      scales[H3_COMPACT_K_SCALE ? bh : bh*blocks+block] = maximum/127.0f;
#pragma unroll
    for (int pack=0; pack<Pack; ++pack) {
      const int64_t s = static_cast<int64_t>(block)*64+lane+pack*(Threads/16);
      if (s < seq) {
        const int64_t off = ((static_cast<int64_t>(b)*seq+s)*heads+h)*PrepD+d;
        __hip_bfloat16 values[8];
        *reinterpret_cast<uint4*>(values) = *reinterpret_cast<const uint4*>(key+off);
        int8_t packed[8];
#pragma unroll
        for (int i=0; i<8; ++i) packed[i] = float_to_int8_nearby_gfx12((__bfloat162float(values[i])-__bfloat162float(means[i]))*inverse);
        *reinterpret_cast<uint2*>(output+off) = *reinterpret_cast<const uint2*>(packed);
      }
    }
  }
}
#if H3_SAMPLE_K_GUARD
__global__ void h3_key_sample_max(const __hip_bfloat16* __restrict__ key,
    const __hip_bfloat16* __restrict__ mean, float* __restrict__ maxima,
    int64_t seq, int64_t heads) {
  const int h = blockIdx.x, b = blockIdx.y;
  const int tid = threadIdx.x, d = (tid % 16) * 8, lane = tid / 16;
  const int64_t bh = static_cast<int64_t>(b) * heads + h;
  const int samples = min(seq, int64_t(H3_SAMPLE_K_GUARD));
  __hip_bfloat16 means[8];
  *reinterpret_cast<uint4*>(means) = *reinterpret_cast<const uint4*>(mean + bh * PrepD + d);
  float maximum = 1.e-7f;
  for (int i = lane; i < samples; i += PrepSeqLanes) {
    const int64_t s = (2 * int64_t(i) + 1) * seq / (2 * samples);
    __hip_bfloat16 values[8];
    *reinterpret_cast<uint4*>(values) = *reinterpret_cast<const uint4*>(key + ((int64_t(b)*seq+s)*heads+h)*PrepD+d);
#pragma unroll
    for (int j=0; j<8; ++j) maximum = fmaxf(maximum, fabsf(__bfloat162float(values[j])-__bfloat162float(means[j])));
  }
  const float block_max = vllm::blockReduceMax(maximum);
  if (tid == 0) maxima[bh] = block_max * (samples == seq ? 1.0f : H3_K_GUARD_MARGIN);
}

template<bool CollectMax, bool Fallback>
__global__ void h3_key_guarded_quant(const __hip_bfloat16* __restrict__ key,
    const __hip_bfloat16* __restrict__ mean, const float* __restrict__ maxima,
    int8_t* __restrict__ output, float* __restrict__ scales, int64_t seq, int64_t heads,
    unsigned int* __restrict__ actual_maxima, const int* __restrict__ head_flags) {
  constexpr int Pack = H3_K_PACK, Threads = 1024 / Pack;
  const int tid = threadIdx.x, d = (tid % 16)*8, lane = tid/16;
  const int h = blockIdx.x, b = blockIdx.z;
  const int64_t bh = static_cast<int64_t>(b)*heads+h;
  if constexpr (Fallback) { if (!head_flags[bh]) return; }
  const int blocks = (seq+63)/64;
  __hip_bfloat16 means[8];
  *reinterpret_cast<uint4*>(means) = *reinterpret_cast<const uint4*>(mean+bh*PrepD+d);
  const float maximum = maxima[bh], inverse = 127.0f/maximum;
  float actual = 1.e-7f;
  for (int group=0; group<H3_K_GROUPS; ++group) {
    const int block = blockIdx.y*H3_K_GROUPS+group;
    if (block >= blocks) break;
    if (tid == 0) scales[bh*blocks+block] = maximum/127.0f;
#pragma unroll
    for (int pack=0; pack<Pack; ++pack) {
      const int64_t s = int64_t(block)*64+lane+pack*(Threads/16);
      if (s < seq) {
        const int64_t off = ((int64_t(b)*seq+s)*heads+h)*PrepD+d;
        __hip_bfloat16 values[8];
        *reinterpret_cast<uint4*>(values) = *reinterpret_cast<const uint4*>(key+off);
        int8_t packed[8];
#pragma unroll
        for (int i=0; i<8; ++i) {
          const float centered = __bfloat162float(values[i])-__bfloat162float(means[i]);
          if constexpr (CollectMax) actual = fmaxf(actual, fabsf(centered));
          packed[i] = float_to_int8_nearby_gfx12(centered*inverse);
        }
        *reinterpret_cast<uint2*>(output+off) = *reinterpret_cast<const uint2*>(packed);
      }
    }
  }
  if constexpr (CollectMax) {
    const float block_max = vllm::blockReduceMax(actual);
    if (tid == 0) {
#if H3_K_GUARD_PARTIAL
      actual_maxima[bh*gridDim.y+blockIdx.y] = __float_as_uint(block_max);
#else
      atomicMax(actual_maxima+bh, __float_as_uint(block_max));
#endif
    }
  }
}

__global__ void h3_choose_key_scale(const float* __restrict__ actual,
    float* __restrict__ estimated, int* __restrict__ head_flags, int64_t count) {
#if H3_K_GUARD_PARTIAL
  const int64_t i = int64_t(blockIdx.y)*gridDim.x+blockIdx.x;
  float maximum = 1.e-7f;
  for (int part=threadIdx.x; part<count; part+=blockDim.x)
    maximum = fmaxf(maximum, actual[i*count+part]);
  maximum = vllm::blockReduceMax(maximum);
  if (threadIdx.x == 0) {
    const bool fallback = maximum > estimated[i];
    head_flags[i] = fallback;
    if (fallback) estimated[i] = maximum;
  }
#else
  const int64_t i = int64_t(blockIdx.x)*blockDim.x+threadIdx.x;
  if (i < count) {
    const bool fallback = actual[i] > estimated[i];
    head_flags[i] = fallback;
    if (fallback) estimated[i] = actual[i];
  }
#endif
}
#endif
#endif
}  // namespace


__global__ void h3_reduce_value_residual(const float* __restrict__ partial,
    float* __restrict__ bias, int64_t seq, int64_t heads, int parts) {
  const int64_t bh = static_cast<int64_t>(blockIdx.y)*heads + blockIdx.x;
  const int d=threadIdx.x;
  float sum=0.0f;
  for(int part=0;part<parts;++part) sum+=partial[(bh*parts+part)*PrepD+d];
  bias[bh*PrepD+d]=sum/static_cast<float>(seq);
}

std::vector<torch::Tensor> prepare_value_fp8_nhd_fused_gfx12(torch::Tensor key, torch::Tensor value) {
#if H3_ORIGINAL_V
  return original_prepare_value_fp8_nhd_fused_gfx12(key, value);
#else
  TORCH_CHECK(key.is_cuda() && value.is_cuda() && key.sizes() == value.sizes() &&
              key.scalar_type() == value.scalar_type(), "prepare_v_fused expects matching K/V");
  TORCH_CHECK(value.dim() == 4 && value.is_contiguous() && key.is_contiguous() &&
              value.scalar_type() == torch::kBFloat16 && value.size(3) == PrepD && value.size(1) > 0,
              "prepare_v_fused expects nonempty contiguous BF16 [B,S,H,128]");
  const int64_t batch = value.size(0), seq = value.size(1), heads = value.size(2);
  const int64_t seq_pad = (seq + 15) / 16 * 16;
  const int parts = (seq + H3_STAT_CHUNK - 1) / H3_STAT_CHUNK;
  auto mean = torch::empty({batch, 1, heads, PrepD}, key.options());
  const int64_t scale_count = batch*heads*PrepD;
  auto scale_storage = torch::empty({2*scale_count}, key.options().dtype(torch::kFloat32));
  auto scales = scale_storage.narrow(0,0,scale_count).view({batch,heads,PrepD});
  auto residuals = torch::empty({batch,heads,(seq+127)/128,PrepD}, key.options().dtype(torch::kFloat32));
  auto output = torch::empty({batch, heads, PrepD, seq_pad}, value.options().dtype(torch::kUInt8));
  const hipStream_t stream = at::hip::getCurrentHIPStreamMasqueradingAsCUDA();
  const dim3 value_grid = H3_HEADS_FIRST ? dim3(heads, (seq + 127) / 128, batch) : dim3((seq + 127) / 128, heads, batch);
#if H3_UNIT_V_GUARD || H3_SAMPLE_V_GUARD
  static_assert(H3_SAMPLE_CENTER > 0, "Unit-scale value preparation requires a separate key-mean kernel");
#if H3_V_GUARD_PARTIAL
  auto maxima = torch::empty({batch, heads, (seq+127)/128, PrepD}, key.options().dtype(torch::kFloat32));
#else
  auto maxima = torch::zeros({batch, heads, PrepD}, key.options().dtype(torch::kFloat32));
#endif
  auto head_flags = torch::empty({batch, heads}, key.options().dtype(torch::kInt32));
  h3_sample_key_mean<<<dim3(heads, batch), PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<__hip_bfloat16*>(mean.data_ptr<at::BFloat16>()), seq, heads,
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()), scales.data_ptr<float>());
  hip_kernel_launch_check();
  h3_parallel_value_quant_transpose<true, false><<<value_grid, PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()),
      scales.data_ptr<float>(), output.data_ptr<uint8_t>(), seq, heads, seq_pad,
      reinterpret_cast<unsigned int*>(maxima.data_ptr<float>()), nullptr, residuals.data_ptr<float>());
  hip_kernel_launch_check();
  h3_choose_value_scale<<<dim3(heads, batch), PrepD, 0, stream>>>(
      maxima.data_ptr<float>(), scales.data_ptr<float>(), head_flags.data_ptr<int>(), heads, (seq+127)/128);
  hip_kernel_launch_check();
  h3_parallel_value_quant_transpose<false, true><<<value_grid, PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()),
      scales.data_ptr<float>(), output.data_ptr<uint8_t>(), seq, heads, seq_pad,
      nullptr, head_flags.data_ptr<int>(), residuals.data_ptr<float>());
  hip_kernel_launch_check();
#else
  auto partial = torch::empty({batch, heads, parts, 2, PrepD}, key.options().dtype(torch::kFloat32));
  const dim3 stats_grid = H3_HEADS_FIRST ? dim3(heads, parts, batch) : dim3(parts, heads, batch);
  h3_partial_kv_statistics<<<stats_grid, PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()),
      partial.data_ptr<float>(), seq, heads, parts);
  hip_kernel_launch_check();
  h3_reduce_kv_statistics<<<dim3(heads, batch), PrepD, 0, stream>>>(
      partial.data_ptr<float>(), reinterpret_cast<__hip_bfloat16*>(mean.data_ptr<at::BFloat16>()),
      scales.data_ptr<float>(), seq, heads, parts);
  hip_kernel_launch_check();
#if H3_SAMPLE_CENTER
  h3_sample_key_mean<<<dim3(heads, batch), PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<__hip_bfloat16*>(mean.data_ptr<at::BFloat16>()), seq, heads,
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()), scales.data_ptr<float>());
  hip_kernel_launch_check();
#endif
  h3_parallel_value_quant_transpose<false, false><<<value_grid, PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(value.data_ptr<at::BFloat16>()),
      scales.data_ptr<float>(), output.data_ptr<uint8_t>(), seq, heads, seq_pad, nullptr, nullptr, residuals.data_ptr<float>());
  hip_kernel_launch_check();
#endif
  h3_reduce_value_residual<<<dim3(heads,batch), PrepD, 0, stream>>>(
      residuals.data_ptr<float>(), scales.data_ptr<float>()+scale_count, seq, heads, (seq+127)/128);
  hip_kernel_launch_check();
  return {mean, output, scales};
#endif
}

std::vector<torch::Tensor> prepare_key_int8_nhd_gfx12(torch::Tensor key, torch::Tensor mean) {
  TORCH_CHECK(key.is_cuda() && mean.is_cuda() && key.dim() == 4 && key.is_contiguous() &&
              key.scalar_type() == torch::kBFloat16 && key.size(3) == PrepD && key.size(1) > 0,
              "prepare_k expects nonempty contiguous BF16 [B,S,H,128]");
  TORCH_CHECK(mean.dim() == 4 && mean.size(0) == key.size(0) && mean.size(1) == 1 &&
              mean.size(2) == key.size(2) && mean.size(3) == PrepD && mean.is_contiguous() &&
              mean.scalar_type() == key.scalar_type(), "prepare_k mean must be BF16 [B,1,H,128]");
  const int64_t batch = key.size(0), seq = key.size(1), heads = key.size(2);
  const int64_t blocks = (seq + 63) / 64;
  auto output = torch::empty_like(key, key.options().dtype(torch::kInt8));
  auto scales = torch::empty({batch, heads, H3_COMPACT_K_SCALE ? int64_t(1) : blocks}, key.options().dtype(torch::kFloat32));
  const hipStream_t stream = at::hip::getCurrentHIPStreamMasqueradingAsCUDA();
#if H3_GLOBAL_K_SCALE
#if H3_SAMPLE_K_GUARD
  static_assert(!H3_COMPACT_K_SCALE, "Guarded key scales use the original scale tensor shape");
  auto maxima = torch::empty({batch, heads}, key.options().dtype(torch::kFloat32));
#if H3_K_GUARD_PARTIAL
  const int64_t parts = (blocks+H3_K_GROUPS-1)/H3_K_GROUPS;
  auto actual = torch::empty({batch, heads, parts}, key.options().dtype(torch::kFloat32));
#else
  auto actual = torch::zeros({batch, heads}, key.options().dtype(torch::kFloat32));
#endif
  auto flags = torch::empty({batch, heads}, key.options().dtype(torch::kInt32));
  h3_key_sample_max<<<dim3(heads,batch), PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()),
      maxima.data_ptr<float>(), seq, heads);
  hip_kernel_launch_check();
  const dim3 key_grid(heads, (blocks+H3_K_GROUPS-1)/H3_K_GROUPS, batch);
  h3_key_guarded_quant<true,false><<<key_grid, 1024/H3_K_PACK, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()), maxima.data_ptr<float>(),
      output.data_ptr<int8_t>(), scales.data_ptr<float>(), seq, heads,
      reinterpret_cast<unsigned int*>(actual.data_ptr<float>()), nullptr);
  hip_kernel_launch_check();
#if H3_K_GUARD_PARTIAL
  h3_choose_key_scale<<<dim3(heads,batch),PrepThreads,0,stream>>>(
      actual.data_ptr<float>(), maxima.data_ptr<float>(), flags.data_ptr<int>(), parts);
#else
  h3_choose_key_scale<<<(batch*heads+127)/128,128,0,stream>>>(
      actual.data_ptr<float>(), maxima.data_ptr<float>(), flags.data_ptr<int>(), batch*heads);
#endif
  hip_kernel_launch_check();
  h3_key_guarded_quant<false,true><<<key_grid, 1024/H3_K_PACK, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()), maxima.data_ptr<float>(),
      output.data_ptr<int8_t>(), scales.data_ptr<float>(), seq, heads, nullptr, flags.data_ptr<int>());
#else
  auto maxima = torch::zeros({batch, heads}, key.options().dtype(torch::kFloat32));
  h3_key_global_max<<<dim3(heads, (seq+H3_STAT_CHUNK-1)/H3_STAT_CHUNK, batch), PrepThreads, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()),
      reinterpret_cast<unsigned int*>(maxima.data_ptr<float>()), seq, heads);
  hip_kernel_launch_check();
  h3_key_global_quant<<<dim3(heads, (blocks+H3_K_GROUPS-1)/H3_K_GROUPS, batch), 1024/H3_K_PACK, 0, stream>>>(
      reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
      reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()), maxima.data_ptr<float>(),
      output.data_ptr<int8_t>(), scales.data_ptr<float>(), seq, heads);
#endif
#else
  const dim3 key_grid = H3_HEADS_FIRST ? dim3(heads, (blocks + H3_K_GROUPS - 1) / H3_K_GROUPS, batch)
                                    : dim3((blocks + H3_K_GROUPS - 1) / H3_K_GROUPS, heads, batch);
  quant_k_nhd_fuse_sub_mean_short_kernel<__hip_bfloat16, PrepD, H3_K_PACK, H3_K_GROUPS>
      <<<key_grid, 64 * 16 / H3_K_PACK, 0, stream>>>(
          reinterpret_cast<const __hip_bfloat16*>(key.data_ptr<at::BFloat16>()),
          reinterpret_cast<const __hip_bfloat16*>(mean.data_ptr<at::BFloat16>()),
          output.data_ptr<int8_t>(), scales.data_ptr<float>(), seq, heads);
#endif
  hip_kernel_launch_check();
  return {output, scales};
}
